package com.pohcosmetictransmogs;

import org.junit.Test;

import static org.junit.Assert.*;

public class TargetSpecTest
{
	@Test
	public void stateIsDeclaredByTheTarget()
	{
		TargetSpec target = new TargetSpec();
		target.objectIds = new int[] {10};
		assertFalse(target.isStateful());
		assertFalse(target.isOpen(10));
		target.objectIds = new int[] {10, 11, 12, 13};
		target.openObjectIds = new int[] {11, 13};
		assertTrue(target.isStateful());
		assertFalse(target.isOpen(10));
		assertTrue(target.isOpen(11));
		assertTrue(target.isOpen(13));
		assertFalse(target.isOpen(18809));
	}
}

package com.pohcosmetictransmogs;

import java.io.StringReader;
import java.util.Collections;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.ObjectComposition;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Test;

import static org.junit.Assert.*;

public class CatalogueTest
{
	@Test
	public void explicitGeometryDoesNotNeedCacheMetadata()
	{
		Client client = ApiDouble.of(Client.class, (name, args) ->
		{
			throw new AssertionError("Unexpected cache lookup: " + name);
		});
		Catalogue catalogue = Catalogue.loadCatalogue(RuneLiteAPI.GSON, client,
			new StringReader("{\"appearances\":{\"gem\":{\"sourceObjectId\":42,\"modelIds\":[10],"
				+ "\"sizeX\":2,\"sizeY\":3,\"scale\":180,\"open\":{\"sourceObjectId\":43,\"modelIds\":[11]}}}}"));
		assertEquals(180, catalogue.appearances.get("gem").open.scaleHeight);
	}

	@Test
	public void placementsInheritTransformsAndExpandGroupedTargets()
	{
		Catalogue catalogue = read("{\"appearances\":{\"gem\":{\"modelIds\":[10],\"scale\":200,"
			+ "\"rotation\":512,\"offsetY\":16,\"flipX\":true,"
			+ "\"placements\":{\"a,b\":{\"scaleX\":250},\"c\":{\"scale\":100,\"scaleHeight\":150,\"flipX\":false}}}}}");
		Catalogue.Recipe gem = catalogue.appearances.get("gem");
		assertEquals(3, gem.placements.size());
		assertSame(gem.placements.get("a"), gem.placements.get("b"));
		Catalogue.Calibration a = gem.placements.get("a");
		assertEquals(250, a.scaleX);
		assertEquals(200, a.scaleY);
		assertEquals(200, a.scaleHeight);
		assertEquals(512, a.rotation);
		assertEquals(16, a.offsetY);
		assertTrue(a.flipX);
		Catalogue.Calibration c = gem.placements.get("c");
		assertEquals(100, c.scaleX);
		assertEquals(100, c.scaleY);
		assertEquals(150, c.scaleHeight);
		assertFalse(c.flipX);
		assertEquals(200, gem.scaleX);
	}

	@Test
	public void statesInheritSharedModelsAndColoursAndCanExplicitlyResetThem()
	{
		Catalogue catalogue = read("{\"appearances\":{\"gem\":{\"modelIds\":[10],\"scale\":180,"
			+ "\"sizeX\":3,\"sizeY\":2,\"animationId\":99,\"spawnAnimationId\":100,\"spawnOnce\":true,"
			+ "\"recolours\":{\"127\":730},\"colours\":{\"CRYSTALS\":[730]},"
			+ "\"closed\":{\"animationId\":98},"
			+ "\"open\":{\"modelIds\":[11],\"animationId\":-1,\"spawnAnimationId\":-1,"
			+ "\"spawnOnce\":false,\"recolours\":{},\"colours\":{}}}}}");
		Catalogue.Recipe gem = catalogue.appearances.get("gem");
		assertArrayEquals(new int[] {10}, gem.closed.modelIds);
		assertEquals(gem.recolours, gem.closed.recolours);
		assertArrayEquals(new short[] {730}, gem.closed.colours(Catalogue.ColourChannel.CRYSTALS));
		assertEquals(98, gem.closed.animationId);
		assertEquals(-1, gem.open.animationId);
		assertEquals(-1, gem.open.spawnAnimationId);
		assertFalse(gem.open.spawnOnce);
		assertEquals(3, gem.open.sizeX);
		assertEquals(2, gem.open.sizeY);
		assertEquals(180, gem.open.scaleX);
		assertTrue(gem.open.recolours.isEmpty());
		assertTrue(gem.open.colours.isEmpty());
		assertEquals(1, gem.recolours.size());
	}

	@Test
	public void fixedRecoloursAndConfigChannelsHaveIndependentEffects()
	{
		Catalogue catalogue = read("{\"appearances\":{\"gem\":{\"modelIds\":[10],"
			+ "\"recolours\":{\"127\":730},\"colours\":{\"PORTAL\":[730]}}}}");
		Catalogue.Recipe gem = catalogue.appearances.get("gem");
		assertEquals(Short.valueOf((short) 730), gem.recolours.get((short) 127));
		assertArrayEquals(new short[] {730}, gem.colours(Catalogue.ColourChannel.PORTAL));
		assertEquals(0, gem.colours(Catalogue.ColourChannel.CRYSTALS).length);
	}

	@Test
	public void everyReaderUsesTheSameCacheAwareNormalization()
	{
		ObjectComposition composition = ApiDouble.of(ObjectComposition.class, (name, args) ->
			name.equals("getSizeX") ? 3 : name.equals("getSizeY") ? 2 : ApiDouble.DEFAULT);
		int[] lookups = {0};
		Client client = ApiDouble.of(Client.class, (name, args) ->
		{
			if (name.equals("getObjectDefinition")) { lookups[0]++; return composition; }
			return ApiDouble.DEFAULT;
		});
		Catalogue catalogue = Catalogue.loadCatalogue(RuneLiteAPI.GSON, client,
			new StringReader("{\"appearances\":{\"a\":{\"sourceObjectId\":42,\"sizeX\":6,\"sizeY\":8}}}"),
			new StringReader("{\"appearances\":{\"b\":{\"sourceObjectId\":42,\"sizeX\":6,\"sizeY\":8}}}"));
		assertEquals(2, lookups[0]);
		for (Catalogue.Recipe recipe : catalogue.appearances.values())
		{
			assertEquals(6, recipe.sizeX);
			assertEquals(8, recipe.sizeY);
			assertEquals(256, recipe.scaleX);
			assertEquals(512, recipe.scaleY);
			assertEquals(256, recipe.scaleHeight);
		}
	}

	@Test
	public void readersAccumulateEntriesInOrder()
	{
		Catalogue catalogue = read(
			"{\"targets\":{\"box\":{\"objectIds\":[1,2],\"openObjectIds\":[2]}}}",
			"{\"appearances\":{\"gem\":{\"modelIds\":[10],\"bindTargets\":[\"box\"]}}}",
			"{\"appearances\":{\"gem\":{\"name\":\"Gem\",\"modelIds\":[11],\"bindTargets\":[\"box\"]}}}");
		assertEquals(1, catalogue.targets.size());
		assertEquals(1, catalogue.appearances.size());
		assertArrayEquals(new int[] {11}, catalogue.appearances.get("gem").modelIds);
		Map<Integer, TargetBinding> bindings = catalogue.bind(Collections.emptyMap());
		assertSame(bindings.get(1), bindings.get(2));
		assertTrue(bindings.get(1).target.isStateful());
	}

	@Test
	public void placementsDoNotCreateBindings()
	{
		Catalogue catalogue = read("{\"targets\":{\"box\":{\"objectIds\":[1]}},"
			+ "\"appearances\":{\"gem\":{\"modelIds\":[10],\"placements\":{\"box\":{\"offsetY\":12}}}}}");
		assertTrue(catalogue.bind(Collections.emptyMap()).isEmpty());
		TargetBinding binding = catalogue.bind(Map.of("box", "gem")).get(1);
		assertEquals(12, binding.calibration(1, 1).offsetY);
	}

	@Test
	public void automaticBindingsUseTheSameTypeAsSelectionFallbacks()
	{
		Catalogue catalogue = read("{\"targets\":{\"a\":{\"objectIds\":[1,2]},"
			+ "\"b\":{\"objectIds\":[3]},\"c\":{\"objectIds\":[4]}},\"appearances\":{"
			+ "\"gem\":{\"modelIds\":[10],\"bindTargets\":[\"a\",\"b\"],"
			+ "\"placements\":{\"a\":{\"scaleX\":200},\"b\":{\"scaleX\":300}}},"
			+ "\"other\":{\"modelIds\":[20]}}}");
		Map<Integer, TargetBinding> bindings = catalogue.bind(Map.of("a", "other", "c", "other"));
		assertEquals("gem", bindings.get(1).appearance.key);
		assertSame(bindings.get(1), bindings.get(2));
		assertSame(bindings.get(1).appearance, bindings.get(3).appearance);
		assertEquals(200, bindings.get(1).calibration(1, 1).scaleX);
		assertEquals(300, bindings.get(3).calibration(1, 1).scaleX);
		assertEquals("other", bindings.get(4).appearance.key);
	}

	@Test
	public void modelMetadataDoesNotDefineAppearanceIdentity()
	{
		Catalogue catalogue = read("{\"appearances\":{"
			+ "\"red\":{\"sourceObjectId\":1,\"modelIds\":[10],\"recolours\":{\"127\":730}},"
			+ "\"blue\":{\"sourceObjectId\":1,\"modelIds\":[10],\"recolours\":{\"127\":44762}},"
			+ "\"explicit\":{\"modelIds\":[10],\"scaleX\":200}}}");
		assertEquals(3, catalogue.appearances.size());
		assertNotSame(catalogue.appearances.get("red"), catalogue.appearances.get("blue"));
		assertEquals(-1, catalogue.appearances.get("explicit").sourceObjectId);
		assertEquals(200, catalogue.appearances.get("explicit").scaleX);
	}

	@Test
	public void missingStatesUseTheDefaultAndOnlyStatefulTargetsSelectStates()
	{
		Catalogue catalogue = read("{\"targets\":{\"static\":{\"objectIds\":[1]},"
			+ "\"container\":{\"objectIds\":[2,3],\"openObjectIds\":[3]}},\"appearances\":{"
			+ "\"gem\":{\"modelIds\":[10],\"open\":{\"modelIds\":[11],\"animationId\":99},"
			+ "\"bindTargets\":[\"static\",\"container\"]}}}");
		Catalogue.Recipe gem = catalogue.appearances.get("gem");
		assertSame(gem, gem.closed);
		assertEquals(-1, gem.animationId);
		assertEquals(99, gem.open.animationId);
		Map<Integer, TargetBinding> bindings = catalogue.bind(Collections.emptyMap());
		assertSame(gem, bindings.get(1).state(1));
		assertSame(gem, bindings.get(2).state(2));
		assertSame(gem.open, bindings.get(3).state(3));
	}

	@Test
	public void targetAndPlacementFitModesRemainIndependentOfModelScale()
	{
		Catalogue catalogue = read("{\"targets\":{\"box\":{\"objectIds\":[1],\"defaultFitMode\":\"FOOTPRINT\"}},"
			+ "\"appearances\":{\"gem\":{\"sizeX\":1,\"sizeY\":1,\"modelIds\":[10],"
			+ "\"scaleX\":200,\"scaleY\":180,\"scaleHeight\":150}}}");
		TargetBinding binding = catalogue.bind(Map.of("box", "gem")).get(1);
		Catalogue.Calibration fit = binding.calibration(2, 3);
		assertEquals(400, fit.scaleX);
		assertEquals(540, fit.scaleY);
		assertEquals(150, fit.scaleHeight);
		Catalogue.Calibration placement = new Catalogue.Calibration();
		placement.fitMode = TargetSpec.FitMode.NONE;
		placement.scaleX = 300;
		binding.appearance.placements.put("box", placement);
		assertEquals(300, binding.calibration(2, 3).scaleX);
		assertEquals(1, binding.appearance.sizeX);
		assertEquals(200, binding.appearance.scaleX);
	}

	@Test
	public void nullReadersAreOptionalAndConsumedReadersAreClosed()
	{
		boolean[] closed = {false};
		StringReader reader = new StringReader("{}")
		{
			@Override
			public void close()
			{
				closed[0] = true;
				super.close();
			}
		};
		Catalogue catalogue = Catalogue.loadCatalogue(RuneLiteAPI.GSON, null, null, reader, new StringReader("  "));
		assertTrue(closed[0]);
		assertTrue(catalogue.targets.isEmpty());
		assertTrue(catalogue.appearances.isEmpty());
	}

	private static Catalogue read(String... inputs)
	{
		StringReader[] readers = new StringReader[inputs.length];
		for (int i = 0; i < inputs.length; i++)
		{
			readers[i] = new StringReader(inputs[i]);
		}
		return Catalogue.loadCatalogue(RuneLiteAPI.GSON, null, readers);
	}
}

package com.pohcosmetictransmogs;

import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.AppearanceOption;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.ArmourAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.ChestAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.EntranceAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.StorageAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.WardrobeAppearance;
import java.util.HashSet;
import java.util.Set;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.BeforeClass;
import org.junit.Test;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class PohCosmeticTransmogsTest
{
	@BeforeClass
	public static void loadCatalogue()
	{
		Catalogue.current = Catalogue.loadCatalogue(RuneLiteAPI.GSON, null, Catalogue.openCatalogueReader());
	}

	@Test
	public void recipesHaveValidModelsAndPlacements()
	{
		Set<String> ids = new HashSet<>();
		assertFalse(Catalogue.current.appearances.values().isEmpty());
		for (Catalogue.Recipe recipe : Catalogue.current.appearances.values())
		{
			assertNotNull(recipe.name);
			assertFalse(recipe.name.trim().isEmpty());
			assertTrue(recipe.name, ids.add(recipe.key));
			for (Catalogue.Definition state : new Catalogue.Definition[]
				{recipe, recipe.closed, recipe.open})
			{
				assertTrue(recipe.name, state.getModelIds().length > 0);
				assertTrue(recipe.name, state.getSizeX() > 0 && state.getSizeY() > 0);
				assertTrue(recipe.name, state.getScaleX() > 0
					&& state.getScaleHeight() > 0 && state.getScaleY() > 0);
				assertNotNull(recipe.name, state.recolours);
			}
			for (Catalogue.Calibration fit : recipe.placements.values())
			{
				assertTrue(recipe.name, fit.getScaleX() > 0 && fit.getScaleHeight() > 0 && fit.getScaleY() > 0);
			}
		}
	}

	@Test
	public void selectablePlacementsHaveExplicitCalibrations()
	{
		for (PohTargetSlot furniture : PohTargetSlot.values())
		{
			for (Catalogue.Recipe recipe : Catalogue.current.appearances.values())
			{
				int id = recipe.getSourceObjectId();
				if (isAllowed(furniture, id))
				{
					assertNotNull(recipe.key + ":" + furniture.getTargetKey(),
						recipe.placements.get(furniture.getTargetKey()));
				}
			}
		}
	}

	@Test
	public void chestRecipesCanShareASourceWithoutSharingTheirClosedState()
	{
		Catalogue.Recipe crystal = Catalogue.current.appearances.get("cox_crystal_chest");
		Catalogue.Recipe chest = Catalogue.current.appearances.get("cox_ancient_chest");
		assertEquals("CoX Crystal Chest", crystal.name);
		assertEquals("CoX Chest", chest.name);
		assertEquals(32752, crystal.transitionModelId);
		assertEquals(7506, crystal.transitionAnimationId);
		assertEquals(20, crystal.transitionHandoff);
		assertEquals(-1, chest.transitionModelId);
		assertTrue(Catalogue.current.appearances.get("cox_crystal_bomb").bobbing);
		assertFalse(chest.bobbing);
		assertEquals(crystal.open.getSourceObjectId(), chest.getSourceObjectId());
		assertArrayEquals(new int[] {32752, 32755}, crystal.closed.getModelIds());
		assertArrayEquals(new int[] {32755}, chest.closed.getModelIds());
		assertArrayEquals(new int[] {32756}, chest.open.getModelIds());
		assertNotEquals(crystal.placements.get("fancy_dress_box"),
			chest.placements.get("fancy_dress_box"));
	}

	@Test
	public void containerAndPortalCalibrationsMatchCatalogue()
	{
		Catalogue.Calibration portal = calibration(PohTargetSlot.ENTRANCE_PORTAL, 41807);
		assertEquals(1024, portal.getRotation());
		assertEquals(232, portal.getScaleX());
		assertEquals(84, portal.getOffsetHeight());

		Catalogue.Calibration chest = calibration(PohTargetSlot.TREASURE_CHEST, 30027);
		assertEquals(512, chest.getRotation());
		Catalogue.Calibration openChest = calibration(PohTargetSlot.TREASURE_CHEST, 30028);
		assertEquals(chest.getScaleX(), openChest.getScaleX());
		assertEquals(chest.getScaleHeight(), openChest.getScaleHeight());
		assertEquals(chest.getScaleY(), openChest.getScaleY());
		assertEquals(128, chest.getScaleX());
		assertEquals(192, chest.getScaleY());
		assertEquals(16, chest.getOffsetY());

		Catalogue.Calibration sarcophagus = calibration(PohTargetSlot.TREASURE_CHEST, 44825);
		assertTrue(sarcophagus.isFlipX());
		assertFalse(calibration(PohTargetSlot.TOY_BOX, 44825).isFlipX());
		assertEquals(-85, sarcophagus.signedScaleX());
		assertEquals(80, sarcophagus.getScaleY());
		assertEquals(
			calibration(PohTargetSlot.TOY_BOX, 29742).getRotation() & 2047,
			calibration(PohTargetSlot.TREASURE_CHEST, 29742).getRotation() & 2047);
		assertEquals(calibration(PohTargetSlot.TOY_BOX, 29742),
			calibration(PohTargetSlot.TREASURE_CHEST, 29742));
		assertNotEquals(calibration(PohTargetSlot.TOY_BOX, 44825), sarcophagus);
		assertNotNull(definition(33012));
		assertArrayEquals(new int[] {35412}, definition(33012).getModelIds());
		assertNull(definition(33013));
		assertEquals(1024, calibration(PohTargetSlot.ARMOUR_CASE, 33012).getRotation());
	}

	@Test
	public void dropdownAllowlistsMatchCataloguePlacements()
	{
		assertEquals(34, EntranceAppearance.values().length - 1);
		assertEquals(17, StorageAppearance.values().length - 1);
		assertEquals(19, ArmourAppearance.values().length - 1);
		assertEquals(18, ChestAppearance.values().length - 1);
		assertEquals(15, WardrobeAppearance.values().length - 1);

		assertTrue(isAllowed(PohTargetSlot.TREASURE_CHEST, 32991));
		assertFalse(isAllowed(PohTargetSlot.CAPE_RACK, 32991));
		assertFalse(isAllowed(PohTargetSlot.ARMOUR_CASE, 33125));
		assertFalse(isAllowed(PohTargetSlot.MAGIC_WARDROBE, 41724));
		assertFalse(isAllowed(PohTargetSlot.MAGIC_WARDROBE, 44825));
		assertTrue(isAllowed(PohTargetSlot.MAGIC_WARDROBE, 6282));
		for (int id : new int[] {4928})
		{
			assertTrue(isAllowed(PohTargetSlot.CAPE_RACK, id));
			assertTrue(isAllowed(PohTargetSlot.ARMOUR_CASE, id));
			assertTrue(isAllowed(PohTargetSlot.TOY_BOX, id));
			assertTrue(isAllowed(PohTargetSlot.TREASURE_CHEST, id));
			assertTrue(isAllowed(PohTargetSlot.FANCY_DRESS_BOX, id));
			assertFalse(isAllowed(PohTargetSlot.MAGIC_WARDROBE, id));
			assertFalse(isAllowed(PohTargetSlot.ENTRANCE_PORTAL, id));
		}
		assertTrue(isAllowed(PohTargetSlot.CAPE_RACK, 32996));
		assertFalse(isAllowed(PohTargetSlot.ARMOUR_CASE, 32996));
		assertFalse(isAllowed(PohTargetSlot.TOY_BOX, 32996));
		assertFalse(isAllowed(PohTargetSlot.TREASURE_CHEST, 32996));
		assertFalse(isAllowed(PohTargetSlot.FANCY_DRESS_BOX, 32996));
	}

	@Test
	public void everyDropdownChoiceHasACompiledRecipe()
	{
		assertRecipes(EntranceAppearance.values());
		assertRecipes(StorageAppearance.values());
		assertRecipes(ArmourAppearance.values());
		assertRecipes(ChestAppearance.values());
		assertRecipes(WardrobeAppearance.values());
	}

	@Test
	public void nodeAndCoxRecolourPalettesAreExplicit()
	{
		assertArrayEquals(new short[] {652, 908, 916, 920, 926},
			definition(61216).colours(Catalogue.ColourChannel.PORTAL));
		assertArrayEquals(new short[] {(short) 38040, (short) 38053, (short) 38309, (short) 38315},
			definition(42819).colours(Catalogue.ColourChannel.NODE_TRIM));
		assertEquals(11, definition(42819).colours(Catalogue.ColourChannel.NODE_BODY).length);
		assertEquals(4, definition(29794).colours(Catalogue.ColourChannel.CRYSTALS).length);
		assertEquals(4, definition(29757).colours(Catalogue.ColourChannel.CRYSTALS).length);
		assertEquals(3, definition(29766).colours(Catalogue.ColourChannel.CRYSTALS).length);
		assertEquals(2, definition(30027).colours(Catalogue.ColourChannel.CRYSTALS).length);
		short[] gauntletChestColours = {
			(short) 32916, (short) 32922, (short) 32926, (short) 32200,
			(short) 29518, (short) 29526, (short) 31192,
			(short) 26776};
		assertArrayEquals(gauntletChestColours,
			definition(36087).colours(Catalogue.ColourChannel.GAUNTLET_CHEST));
		assertArrayEquals(gauntletChestColours,
			definition(36088).colours(Catalogue.ColourChannel.GAUNTLET_CHEST));
		assertArrayEquals(new short[] {(short) 55219},
			definition(32991).colours(Catalogue.ColourChannel.TOB_CHEST));
		assertArrayEquals(definition(32991).colours(Catalogue.ColourChannel.TOB_CHEST),
			definition(41746).colours(Catalogue.ColourChannel.TOB_CHEST));
		assertArrayEquals(new short[] {(short) 54177},
			definition(4928).colours(Catalogue.ColourChannel.CRYSTALS));
		assertArrayEquals(new short[] {
			(short) 53582, (short) 52403, (short) 52407, (short) 52416,
			(short) 52424, (short) 51515, (short) 51484},
			definition(32996).colours(Catalogue.ColourChannel.CRYSTALS));
		assertArrayEquals(new short[] {(short) 960, (short) 794, (short) 914},
			definition(33125).colours(Catalogue.ColourChannel.DEADMAN_CHEST));
		assertArrayEquals(definition(33125).colours(Catalogue.ColourChannel.DEADMAN_CHEST),
			definition(31583).colours(Catalogue.ColourChannel.DEADMAN_CHEST));
		assertEquals(23, definition(44825).colours(Catalogue.ColourChannel.TOA_CONTAINERS).length);
		short[] toaChestColours = definition(44788).colours(Catalogue.ColourChannel.TOA_CONTAINERS);
		assertEquals(17, toaChestColours.length);
		assertArrayEquals(toaChestColours,
			definition(44789).colours(Catalogue.ColourChannel.TOA_CONTAINERS));
		assertArrayEquals(toaChestColours,
			definition(41696).colours(Catalogue.ColourChannel.TOA_CONTAINERS));
		assertArrayEquals(toaChestColours,
			definition(44791).colours(Catalogue.ColourChannel.TOA_CONTAINERS));
		for (int chestColour : new int[] {6315, 6348, 6592, 6674, 6817, 6819,
			6823, 6825, 6827, 6833, 6837, 6839, 6848, 6856, 6864, 6868, 6872})
		{
			assertTrue(contains(toaChestColours, (short) chestColour));
		}
		for (int coinColour : new int[] {7384, 7690, 7349, 7343, 7506, 7500,
			7492, 8123, 7616, 5943, 6986})
		{
			assertFalse(contains(definition(44825).colours(Catalogue.ColourChannel.TOA_CONTAINERS),
				(short) coinColour));
			assertFalse(contains(toaChestColours, (short) coinColour));
		}
		for (int retainedColour : new int[] {5281, 5293, 6336, 6379, 6976})
		{
			assertFalse(contains(definition(44825).colours(Catalogue.ColourChannel.TOA_CONTAINERS),
				(short) retainedColour));
		}
		assertEquals(14, PohCosmeticTransmogsConfig.AppearanceColour.GREEN.getHue());
	}

	@Test
	public void crystalModelsUseCalibratedTransforms()
	{
		assertArrayEquals(new int[] {4895}, definition(4928).getModelIds());
		assertEquals("Crystal Outcrop", Catalogue.name(key(4928)));
		assertNull(definition(4927));
		for (PohTargetSlot slot : PohTargetSlot.values())
		{
			assertFalse(isAllowed(slot, 4927));
		}
		assertArrayEquals(new int[] {35449}, definition(32996).getModelIds());
		assertEquals(160, calibration(PohTargetSlot.TREASURE_CHEST, 4928).getScaleX());
		assertEquals(96, calibration(PohTargetSlot.TREASURE_CHEST, 4928).getScaleY());
		assertEquals(calibration(PohTargetSlot.TREASURE_CHEST, 4928),
			calibration(PohTargetSlot.TOY_BOX, 4928));

		Catalogue.Calibration crystal =
			calibration(PohTargetSlot.CAPE_RACK, 32996);
		assertEquals(128, crystal.getScaleX());
		assertEquals(128, crystal.getScaleHeight());
		assertEquals(128, crystal.getScaleY());

