package com.pohcosmetictransmogs;

/** One selected recipe shared by every scene ID of a logical target. */
final class TargetBinding
{
	final TargetSpec target;
	final Catalogue.Recipe appearance;

	TargetBinding(TargetSpec target, Catalogue.Recipe appearance)
	{
		this.target = target;
		this.appearance = appearance;
	}

	Catalogue.Definition state(int objectId)
	{
		return target.isStateful() ? appearance.state(target.isOpen(objectId)) : appearance;
	}

	Catalogue.Calibration calibration(int sizeX, int sizeY)
	{
		return Catalogue.ModelFactory.calibration(appearance, target,
			target.sizeX > 0 ? target.sizeX : sizeX,
			target.sizeY > 0 ? target.sizeY : sizeY);
	}
}

package com.pohcosmetictransmogs;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.io.StringReader;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.api.events.WorldViewUnloaded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "PoH Cosmetic Transmogs",
	description = "Transmog specific PoH slot and props into curated, whitelisted cosmetic objects",
	tags = {"poh", "house", "slot", "cosmetic", "transmog"}
)
public class PohCosmeticTransmogsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private PohCosmeticTransmogsConfig config;

	@Inject
	private PohCosmeticTransmogsManager manager;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private PohCosmeticTransmogsOverlay overlay;

	private final RenderCallback renderCallback = new RenderCallback()
	{
		@Override
		public boolean drawObject(Scene scene, TileObject object)
		{
			return manager.shouldDrawObject(object);
		}
	};

	private int sceneScanTicksRemaining;
	private volatile boolean enabled;
	private boolean managerStarted;
	private boolean rendererWarningShown;
	private boolean overlayAdded;

	@Provides
	PohCosmeticTransmogsConfig provideConfig(ConfigManager manager, Gson gson)
	{
		if (Catalogue.current.appearances.isEmpty())
		{
			Catalogue.current = Catalogue.loadCatalogue(gson, null, Catalogue.openCatalogueReader());
		}
		return manager.getConfig(PohCosmeticTransmogsConfig.class);
	}

	@Override
	protected void startUp()
	{
		enabled = true;
		managerStarted = false;
		rendererWarningShown = false;
		renderCallbackManager.register(renderCallback);
		updateShapeOverlay();
		clientThread.invokeLater(() ->
		{
			if (!enabled)
			{
				return;
			}
			reloadCatalogue();
			updateRenderer();
		});
	}

	@Override
	protected void shutDown()
	{
		enabled = false;
		renderCallbackManager.unregister(renderCallback);
		updateShapeOverlay();
		clientThread.invoke(manager::stop);
		sceneScanTicksRemaining = 0;
		managerStarted = false;
		rendererWarningShown = false;
	}

	@Override
	public void resetConfiguration()
	{
		Map<String, String> selections = new LinkedHashMap<>();
		for (PohTargetSlot slot : PohTargetSlot.values())
		{
			String key = slot.getConfigKey();
			Enum<?> original = slot.option("");
			if (!original.name().equals(configManager.getConfiguration(PohCosmeticTransmogsConfig.GROUP, key)))
			{
				configManager.setConfiguration(PohCosmeticTransmogsConfig.GROUP, key, original);
			}
		}
		clientThread.invokeLater(() -> manager.setSelections(selections));
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PohCosmeticTransmogsConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if (PohTargetSlot.isConfigKey(event.getKey()))
		{
			clientThread.invokeLater(() -> manager.setSelections(readSelections()));
			return;
		}

		switch (event.getKey())
		{
			case "pohtransmogs":
				clientThread.invokeLater(this::reloadCatalogue);
				break;
			case "hideFurnitureTransmogs":
				clientThread.invokeLater(() -> manager.setHidden(config.hideFurnitureTransmogs()));
				break;
			case "outlineOriginalClickbox":
				updateShapeOverlay();
				break;
			case "portalColour":
			case "recolourPortalsInAllPositions":
			case "recolourColour":
			case "recolourCoxCrystals":
			case "recolourTobChest":
			case "recolourGauntletChest":
			case "recolourDeadmanChest":
			case "recolourToaSarcophagus":
			case "recolourNodePortal":
				clientThread.invokeLater(manager::refreshColours);
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			reloadCatalogue();
			manager.setSelections(readSelections());
		});
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateRenderer();
		if (!managerStarted)
		{
			return;
		}
		manager.syncVisibleLevels();
		manager.loadMissingModels();
		if (sceneScanTicksRemaining > 0)
		{
			manager.reconcileLoadedWorldViews();
			sceneScanTicksRemaining--;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			sceneScanTicksRemaining = 0;
			manager.clearSceneState();
		}
		else if (event.getGameState() == GameState.LOADING)
		{
			manager.clearSceneState();
			sceneScanTicksRemaining = 3;
		}
		else if (event.getGameState() == GameState.LOGGED_IN)
		{
			manager.refreshColours();
			manager.reconcileLoadedWorldViews();
			sceneScanTicksRemaining = Math.max(sceneScanTicksRemaining, 2);
		}
	}

	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		manager.scanWorldView(event.getWorldView());
		sceneScanTicksRemaining = Math.max(sceneScanTicksRemaining, 2);
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		manager.removeWorldView(event.getWorldView());
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		manager.addObject(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		manager.removeObject(event.getGameObject());
	}

	private void updateRenderer()
	{
		if (!enabled)
		{
			return;
		}
		if (manager.isSupportedRenderer())
		{
			rendererWarningShown = false;
			if (!managerStarted)
			{
				manager.start(readSelections(), config.hideFurnitureTransmogs());
				managerStarted = true;
				updateShapeOverlay();
			}
		}
		else
		{
			if (managerStarted)
			{
				manager.stop();
				managerStarted = false;
				updateShapeOverlay();
			}
			// Chat is not visible at the login screen; report the pause after login.
			if (!rendererWarningShown && client.getGameState() == GameState.LOGGED_IN)
			{
				client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
					"PoH Cosmetic Transmogs is paused. Enable GPU or 117 HD to resume automatically. GPU Legacy is not supported.", null);
				rendererWarningShown = true;
			}
		}
	}

	private void updateShapeOverlay()
	{
		boolean shouldAdd = enabled && managerStarted && config.outlineOriginalShape();
		if (shouldAdd == overlayAdded)
		{
			return;
		}
		overlayAdded = shouldAdd;
		if (shouldAdd)
		{
			overlayManager.add(overlay);
		}
		else
		{
			overlayManager.remove(overlay);
			overlay.reset();
		}
	}

	private void reloadCatalogue()
	{
		Catalogue.current = Catalogue.loadCatalogue(gson, client, Catalogue.openCatalogueReader(),
			new StringReader(java.util.Objects.toString(configManager.getConfiguration(
				PohCosmeticTransmogsConfig.GROUP, "pohtransmogs"), "{}")));
		manager.setCatalogue(Catalogue.current);
	}

	private Map<String, String> readSelections()
	{
		Map<String, String> selections = new LinkedHashMap<>();
		for (PohTargetSlot slot : PohTargetSlot.values())
		{
			selections.put(slot.getTargetKey(), readAppearanceKey(slot));
		}
		return selections;
	}

	private String readAppearanceKey(PohTargetSlot slot)
	{
		switch (slot)
		{
			case ENTRANCE_PORTAL: return config.entrancePortal().getAppearanceKey();
			case FANCY_DRESS_BOX: return config.fancyDressBox().getAppearanceKey();
			case MAGIC_WARDROBE: return config.magicWardrobe().getAppearanceKey();
			case TREASURE_CHEST: return config.treasureChest().getAppearanceKey();
			case CAPE_RACK: return config.capeRack().getAppearanceKey();
			case ARMOUR_CASE: return config.armourCase().getAppearanceKey();
			case TOY_BOX: return config.toyBox().getAppearanceKey();
			default: throw new IllegalArgumentException(slot.name());
		}
	}

}

package com.pohcosmetictransmogs;

/** Scene IDs and placement semantics for one logical target. */
final class TargetSpec
{
	String key;
	int[] objectIds = {};
	int[] openObjectIds = {};
	int sizeX;
	int sizeY;
	int orientationOffset;
	boolean scaleTransition;
	boolean portalRecolour;
	FitMode defaultFitMode = FitMode.NONE;

	enum FitMode
	{
		NONE,
		FOOTPRINT
	}

	boolean isOpen(int objectId)
	{
		for (int id : openObjectIds)
		{
			if (id == objectId)
			{
				return true;
			}
		}
		return false;
	}

	boolean isStateful()
	{
		return openObjectIds.length > 0;
	}

}

package com.pohcosmetictransmogs;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.JagexColor;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.ObjectComposition;
import net.runelite.api.gameval.VarbitID;

/** Indexed target semantics, appearance recipes and model construction. */
final class Catalogue
{
	private static final int NATIVE_MODEL_SCALE = 128;
	private static final int[] NO_IDS = {};
	private static final short[] NO_COLOURS = {};
	static volatile Catalogue current = new Catalogue(new CatalogueData());
	final Map<String, TargetSpec> targets;
	final Map<String, Recipe> appearances;

	private Catalogue(CatalogueData data)
	{
		targets = Collections.unmodifiableMap(data.targets);
		appearances = Collections.unmodifiableMap(data.appearances);
	}

	static Catalogue loadCatalogue(Gson gson, @Nullable Client client, Reader... readers)
	{
		CatalogueData data = new CatalogueData();
		for (Reader reader : readers)
		{
			if (reader != null)
			{
				try (Reader input = reader)
				{
					readIntoCatalogue(gson, client, input, data);
				}
				catch (IOException ex)
				{
					throw new IllegalStateException("Unable to read catalogue", ex);
				}
			}
		}
		return new Catalogue(data);
	}

	static Reader openCatalogueReader()
	{
		InputStream stream = Catalogue.class.getResourceAsStream("/catalogue.json");
		if (stream == null)
		{
			throw new IllegalStateException("Missing catalogue.json");
		}
		return new InputStreamReader(stream, StandardCharsets.UTF_8);
	}

	private static void readIntoCatalogue(Gson gson, @Nullable Client client,
		Reader reader, CatalogueData data)
	{
		JsonObject json = gson.fromJson(reader, JsonObject.class);
		if (json == null)
		{
			return;
		}
		if (json.has("targets"))
		{
			for (Map.Entry<String, JsonElement> entry : json.getAsJsonObject("targets").entrySet())
			{
				TargetSpec target = gson.fromJson(entry.getValue(), TargetSpec.class);
				target.key = entry.getKey();
				data.targets.put(target.key, target);
			}
		}
		if (json.has("appearances"))
		{
			for (Map.Entry<String, JsonElement> entry : json.getAsJsonObject("appearances").entrySet())
			{
				JsonObject source = entry.getValue().getAsJsonObject();
				Recipe recipe = gson.fromJson(expandScale(source), Recipe.class);
				recipe.key = entry.getKey();
				recipe.normalize(client);
				JsonObject defaults = gson.toJsonTree(recipe, Definition.class).getAsJsonObject();
				recipe.closed = readState(gson, client, source, "closed", defaults, recipe);
				recipe.open = readState(gson, client, source, "open", defaults, recipe);
				if (source.has("placements"))
				{
					for (Map.Entry<String, JsonElement> placement : source.getAsJsonObject("placements").entrySet())
					{
						Calibration calibration = gson.fromJson(overlay(defaults,
							expandScale(placement.getValue().getAsJsonObject())), Calibration.class);
						for (String target : placement.getKey().split(","))
						{
							recipe.placements.put(target.trim(), calibration);
						}
					}
				}
				data.appearances.put(recipe.key, recipe);
			}
		}
	}

	private static Definition readState(Gson gson, @Nullable Client client, JsonObject source,
		String name, JsonObject defaults, Recipe recipe)
	{
		if (!source.has(name))
		{
			return recipe;
		}
		Definition state = gson.fromJson(overlay(defaults,
			expandScale(source.getAsJsonObject(name))), Definition.class);
		state.normalize(client);
		return state;
	}

	private static JsonObject expandScale(JsonObject source)
	{
		JsonObject result = source.deepCopy();
		if (source.has("scale"))
		{
			for (String axis : new String[] {"scaleX", "scaleHeight", "scaleY"})
			{
				if (!source.has(axis)) { result.add(axis, source.get("scale")); }
			}
		}
		return result;
	}

	private static JsonObject overlay(JsonObject defaults, JsonObject overrides)
	{
		JsonObject result = defaults.deepCopy();
		overrides.entrySet().forEach(entry -> result.add(entry.getKey(), entry.getValue()));
		return result;
	}

	static String name(String appearanceKey)
	{
		Recipe recipe = current.appearances.get(appearanceKey);
		return appearanceKey.isEmpty() ? "Original" : recipe == null ? appearanceKey : recipe.name;
	}

	Map<Integer, TargetBinding> bind(Map<String, String> selections)
	{
		Map<String, TargetBinding> bindings = new LinkedHashMap<>();
		for (Recipe recipe : appearances.values())
		{
			for (String key : recipe.bindTargets)
			{
				bind(bindings, key, recipe);
			}
		}
		selections.forEach((key, appearanceKey) ->
		{
			if (!bindings.containsKey(key))
			{
				bind(bindings, key, appearances.get(appearanceKey));
			}
		});
		Map<Integer, TargetBinding> byId = new LinkedHashMap<>();
		for (TargetBinding binding : bindings.values())
		{
			for (int id : binding.target.objectIds)
			{
				byId.putIfAbsent(id, binding);
			}
		}
		return byId;
	}

	private void bind(Map<String, TargetBinding> bindings, String key, @Nullable Recipe recipe)
	{
		TargetSpec target = targets.get(key);
		if (target != null && recipe != null)
		{
			bindings.put(key, new TargetBinding(target, recipe));
		}
	}

	private static final class CatalogueData
	{
		final Map<String, TargetSpec> targets = new LinkedHashMap<>();
		final Map<String, Recipe> appearances = new LinkedHashMap<>();
	}

	/** Appearance identity and optional container states; inherited fields form its default state. */
	static final class Recipe extends Definition
	{
		String key;
		String name;
		String category;
		transient Definition closed;
		transient Definition open;
		String[] bindTargets = {};
		Alignment alignment = Alignment.NONE;
		boolean bobbing;
		int transitionModelId = -1;
		int transitionAnimationId = -1;
		int transitionHandoff;
		transient Map<String, Calibration> placements = new LinkedHashMap<>();

		Definition state(boolean opened)
		{
			return opened ? open : closed;
		}

		String stateKey(Definition state)
		{
			return state == this ? "default" : state == closed ? "closed" : "open";
		}
	}

	enum ColourChannel
	{
		PORTAL, CRYSTALS, TOB_CHEST, GAUNTLET_CHEST, DEADMAN_CHEST, TOA_CONTAINERS, NODE_TRIM, NODE_BODY;

		boolean enabled(PohCosmeticTransmogsConfig config)
		{
			switch (this)
			{
				case CRYSTALS: return config.recolourCrystals();
				case TOB_CHEST: return config.recolourTobChest();
				case GAUNTLET_CHEST: return config.recolourGauntletChest();
				case DEADMAN_CHEST: return config.recolourDeadmanChest();
				case TOA_CONTAINERS: return config.recolourToaContainers();
				default: return false;
			}
		}
	}

	enum Alignment
	{
		NONE(0, 0),
		SOUTH_WEST(-1, -1),
		SOUTH_EAST(1, -1),
		NORTH_WEST(-1, 1),
		NORTH_EAST(1, 1);

		final int x;
		final int y;

		Alignment(int x, int y)
		{
			this.x = x;
			this.y = y;
		}
	}

	@Getter
	@EqualsAndHashCode
	static class Calibration
	{
		int rotation;
		int scaleX = NATIVE_MODEL_SCALE;
		int scaleHeight = NATIVE_MODEL_SCALE;
		int scaleY = NATIVE_MODEL_SCALE;
		// Horizontal offsets are relative to the normalized target orientation.
		int offsetX;
		int offsetHeight;
		int offsetY;
		boolean flipX;
		TargetSpec.FitMode fitMode;

		Calibration()
		{
		}

		Calibration(int rotation, int scaleX, int scaleHeight, int scaleY,
			int offsetX, int offsetHeight, int offsetY)
		{
			this.rotation = rotation;
			this.scaleX = scaleX;
			this.scaleHeight = scaleHeight;
			this.scaleY = scaleY;
			this.offsetX = offsetX;
			this.offsetHeight = offsetHeight;
			this.offsetY = offsetY;
		}

		int signedScaleX()
		{
			return flipX ? -scaleX : scaleX;
		}

	}

	@Getter
	@EqualsAndHashCode(callSuper = true)
	static class Definition extends Calibration
	{
		int sourceObjectId = -1;
		int sizeX;
		int sizeY;
		int[] modelIds = NO_IDS;
		int animationId = -1;
		int spawnAnimationId = -1;
		boolean spawnOnce;
		Map<Short, Short> recolours = new LinkedHashMap<>();
		Map<ColourChannel, short[]> colours = new LinkedHashMap<>();
		int portalSaturation = -1;

		short[] colours(ColourChannel channel)
		{
			return colours.getOrDefault(channel, NO_COLOURS);
		}

		Definition()
		{
			scaleX = scaleHeight = scaleY = 0;
		}

		void normalize(@Nullable Client client)
		{
			ObjectComposition source = client != null && sourceObjectId >= 0
				&& (sizeX == 0 || sizeY == 0 || scaleX == 0 || scaleY == 0)
				? client.getObjectDefinition(sourceObjectId) : null;
			int nativeSizeX = source == null ? Math.max(1, sizeX) : source.getSizeX();
			int nativeSizeY = source == null ? Math.max(1, sizeY) : source.getSizeY();
			if (sizeX == 0)
			{
				sizeX = nativeSizeX;
			}
			if (sizeY == 0)
			{
				sizeY = nativeSizeY;
			}
			if (scaleX == 0)
			{
				scaleX = ModelFactory.footprintScale(NATIVE_MODEL_SCALE, sizeX, nativeSizeX);
			}
			if (scaleY == 0)
			{
				scaleY = ModelFactory.footprintScale(NATIVE_MODEL_SCALE, sizeY, nativeSizeY);
			}
			if (scaleHeight == 0)
			{
				scaleHeight = Math.min(scaleX, scaleY);
			}
		}

		Definition(int sizeX, int sizeY, int[] modelIds, int animationId)
		{
			this.sizeX = sizeX;
			this.sizeY = sizeY;
			this.modelIds = modelIds;
			this.animationId = animationId;
			scaleX = NATIVE_MODEL_SCALE;
			scaleHeight = NATIVE_MODEL_SCALE;
			scaleY = NATIVE_MODEL_SCALE;
		}
	}

	static final class ModelFactory
	{
		private final Client client;
		private final PohCosmeticTransmogsConfig config;

		ModelFactory(Client client, PohCosmeticTransmogsConfig config)
		{
			this.client = client;
			this.config = config;
		}

		static Calibration calibration(Recipe recipe, TargetSpec target, int targetSizeX, int targetSizeY)
		{
			Calibration selected = recipe.placements.getOrDefault(target.key, recipe);
			TargetSpec.FitMode fit = selected.fitMode == null ? target.defaultFitMode : selected.fitMode;
			if (fit == TargetSpec.FitMode.NONE)
			{
				return selected;
			}
			if (isQuarterTurn(selected.rotation))
			{
				int swap = targetSizeX;
				targetSizeX = targetSizeY;
				targetSizeY = swap;
			}
			Calibration result = new Calibration(selected.rotation,
				footprintScale(selected.scaleX, targetSizeX, recipe.sizeX), selected.scaleHeight,
				footprintScale(selected.scaleY, targetSizeY, recipe.sizeY),
				selected.offsetX, selected.offsetHeight, selected.offsetY);
			result.flipX = selected.flipX;
			return result;
		}

		boolean recoloursPortal(TargetSpec target, Definition definition)
		{
			return config.portalColour().getHue() >= 0
				&& definition.colours(ColourChannel.PORTAL).length > 0
				&& (target.portalRecolour
					|| config.recolourPortalsInAllPositions());
		}

		@Nullable
		Model load(TargetSpec target, Definition definition, Calibration calibration)
		{
			ModelData[] parts = new ModelData[definition.getModelIds().length];
			for (int i = 0; i < parts.length; i++)
			{
				parts[i] = client.loadModelData(definition.getModelIds()[i]);
				if (parts[i] == null)
				{
					return null;
				}
			}
			// Merging also gives mirrored recipes their own face-index arrays; a
			// shallow copy would reverse RuneLite's shared cached model in place.
			ModelData model = client.mergeModels(parts, parts.length);
			if (model == null)
			{
				return null;
			}
			model.cloneVertices();
			model.cloneColors();
			definition.recolours.forEach((from, to) -> model.recolor(from, to));
			if (recoloursPortal(target, definition))
			{
				recolorHue(model, definition.colours(ColourChannel.PORTAL), config.portalColour().getHue(),
					definition.getPortalSaturation());
			}
			int hue = config.recolourColour().getHue();
			if (hue >= 0)
			{
				for (Map.Entry<ColourChannel, short[]> channel : definition.colours.entrySet())
				{
					if (channel.getKey().enabled(config))
					{
						recolorHue(model, channel.getValue(), hue, -1);
					}
				}
			}
			if (config.recolourNodePortal() && definition.colours(ColourChannel.NODE_TRIM).length > 0)
			{
				recolorNodePortal(model, definition);
			}

			// Animation transforms use the cache model's original coordinate system.
			// Animated recipes are therefore resized after each posed frame by the
			// manager; preprocessing their vertices makes moving parts drift away.
			if (definition.getAnimationId() < 0)
			{
				model.scale(calibration.getScaleX(), calibration.getScaleHeight(), calibration.getScaleY());
				model.translate(0, calibration.getOffsetHeight(), 0);
			}
			Model lit = model.light();
			if (calibration.isFlipX())
			{
				if (definition.getAnimationId() < 0)
				{
					// Static geometry already has its magnitude; reflect it after
					// lighting so its normals can be mirrored deliberately below.
					lit.scale(-128, 128, 128);
				}
				correctMirroredWinding(lit);
			}
			return lit;
		}

		private static void correctMirroredWinding(Model model)
		{
			swap(model.getFaceIndices1(), model.getFaceIndices3());
			swap(model.getFaceColors1(), model.getFaceColors3());
			swap(model.getTexIndices1(), model.getTexIndices3());
			negate(model.getVertexNormalsX());
		}

		private static void swap(@Nullable int[] first, @Nullable int[] third)
		{
			if (first == null || third == null)
			{
				return;
			}
			for (int i = 0; i < Math.min(first.length, third.length); i++)
			{
				int value = first[i];
				first[i] = third[i];
				third[i] = value;
			}
		}

		private static void negate(@Nullable int[] values)
		{
			if (values != null)
			{
				for (int i = 0; i < values.length; i++)
				{
					values[i] = -values[i];
				}
			}
		}

		private static void recolorHue(ModelData model, short[] sources, int hue, int saturationOverride)
		{
			recolorHue(model, sources, hue, saturationOverride, 0);
		}

		private void recolorNodePortal(ModelData model, Definition definition)
		{
			int accountType = client.getVarbitValue(VarbitID.IRONMAN);
			switch (accountType)
			{
				case 1: // Ironman - grey
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 0, 0);
					break;
				case 2: // Ultimate ironman - light grey
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 0, 0, 20);
					break;
				case 3: // Hardcore ironman - red
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 0, 6);
					recolorHue(model, definition.colours(ColourChannel.NODE_BODY), 0, 6);
					break;
				case 4: // Ranked group ironman native
					break;
				case 5: // Hardcore group ironman - red trim
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 0, 6);
					break;
				case 6: // Unranked group ironman - green trim
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 14, 6);
					break;
				default: // Main - bronze
					recolorHue(model, definition.colours(ColourChannel.NODE_TRIM), 5, 4);
					recolorHue(model, definition.colours(ColourChannel.NODE_BODY), 5, 4);
					break;
			}
		}

		private static void recolorHue(ModelData model, short[] sources,
			int hue, int saturationOverride, int luminanceOffset)
		{
			for (short source : sources)
			{
				int saturation = saturationOverride >= 0
					? saturationOverride : JagexColor.unpackSaturation(source);
				int luminance = Math.max(0, Math.min(127,
					JagexColor.unpackLuminance(source) + luminanceOffset));
				model.recolor(source, JagexColor.packHSL(hue, saturation, luminance));
			}
		}

		static boolean isQuarterTurn(int orientation)
		{
			return (orientation & 1023) == 512;
		}

		static int footprintScale(int nativeScale, int targetTiles, int sourceTiles)
		{
			return Math.max(1, Math.round((float) nativeScale * targetTiles / Math.max(1, sourceTiles)));
		}

	}
}

package com.pohcosmetictransmogs;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.TileObject;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class PohCosmeticTransmogsOverlay extends Overlay
{
	private final PohCosmeticTransmogsConfig config;
	private final PohCosmeticTransmogsManager manager;
	private final Client client;
	private final Map<TileObject, Shape> shapes = new IdentityHashMap<>();
	private int cameraX = Integer.MIN_VALUE;
	private int cameraY;
	private int cameraZ;
	private int cameraPitch;
	private int cameraYaw;
	private int viewportWidth;
	private int viewportHeight;
	private int viewportXOffset;
	private int viewportYOffset;
	private int viewportScale;
	private int strokeWidth = -1;
	private Stroke stroke;

	@Inject
	private PohCosmeticTransmogsOverlay(
		PohCosmeticTransmogsConfig config, PohCosmeticTransmogsManager manager, Client client)
	{
		this.config = config;
		this.manager = manager;
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public synchronized Dimension render(Graphics2D graphics)
	{
		refreshProjectionCache();
		graphics.setColor(config.originalShapeColor());
		int configuredStrokeWidth = config.originalShapeWidth();
		if (strokeWidth != configuredStrokeWidth)
		{
			strokeWidth = configuredStrokeWidth;
			stroke = new BasicStroke(configuredStrokeWidth);
		}
		graphics.setStroke(stroke);
		WorldView topLevel = client.getTopLevelWorldView();
		Set<TileObject> activeObjects = manager.getActiveObjects();
		shapes.keySet().removeIf(object -> !activeObjects.contains(object));
		for (TileObject object : activeObjects)
		{
			WorldView worldView = object.getWorldView();
			if (worldView == null || object.getPlane() != worldView.getPlane())
			{
				continue;
			}
			WorldEntity worldEntity = topLevel == null
				? null : topLevel.worldEntities().byIndex(worldView.getId());
			if (worldEntity != null && worldEntity.isHiddenForOverlap())
			{
				continue;
			}
			Shape shape = shapes.get(object);
			if (shape == null)
			{
				shape = object.getClickbox();
				if (shape != null)
				{
					shapes.put(object, shape);
				}
			}
			if (shape != null)
			{
				graphics.draw(shape);
			}
		}
		return null;
	}

	synchronized void reset()
	{
		shapes.clear();
		cameraX = Integer.MIN_VALUE;
	}

	private void refreshProjectionCache()
	{
		int newCameraX = client.getCameraX();
		int newCameraY = client.getCameraY();
		int newCameraZ = client.getCameraZ();
		int newCameraPitch = client.getCameraPitch();
		int newCameraYaw = client.getCameraYaw();
		int newViewportWidth = client.getViewportWidth();
		int newViewportHeight = client.getViewportHeight();
		int newViewportXOffset = client.getViewportXOffset();
		int newViewportYOffset = client.getViewportYOffset();
		int newViewportScale = client.getScale();
		boolean viewChanged = cameraX != newCameraX || cameraY != newCameraY || cameraZ != newCameraZ
			|| cameraPitch != newCameraPitch || cameraYaw != newCameraYaw
			|| viewportWidth != newViewportWidth || viewportHeight != newViewportHeight
			|| viewportXOffset != newViewportXOffset || viewportYOffset != newViewportYOffset
			|| viewportScale != newViewportScale;
		if (viewChanged)
		{
			shapes.clear();
			cameraX = newCameraX;
			cameraY = newCameraY;
			cameraZ = newCameraZ;
			cameraPitch = newCameraPitch;
			cameraYaw = newCameraYaw;
			viewportWidth = newViewportWidth;
			viewportHeight = newViewportHeight;
			viewportXOffset = newViewportXOffset;
			viewportYOffset = newViewportYOffset;
			viewportScale = newViewportScale;
		}
	}
}

package com.pohcosmetictransmogs;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.EqualsAndHashCode;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Model;
import net.runelite.api.Point;
import net.runelite.api.Perspective;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.api.widgets.Widget;

/**
 * Manages cosmetic replacements while retaining the original scene objects.
 * The original GameObject continues to own actions and collision.
 */
@Singleton
@Slf4j
class PohCosmeticTransmogsManager
{
	private static final int SCALE_TRANSITION_DURATION = 30;
	private final Client client;
	private final Catalogue.ModelFactory modelFactory;
	private final Map<String, String> selections = new HashMap<>();
	private final Map<ModelCacheKey, Model> modelCache = new HashMap<>();
	private final Map<Integer, TargetBinding> targetsById = new HashMap<>();
	private final Set<String> reportedModelFailures = new HashSet<>();
	private final Set<TileObject> sceneObjects = identitySet();
	private final Set<TileObject> retiredObjects = identitySet();
	private final Set<TileObject> suppressedObjects = identitySet();
	private final Map<TileObject, RuneLiteObject> activeReplacements = new IdentityHashMap<>();
	private final Map<RuneLiteObject, RuneLiteObject> transitionEffects = new IdentityHashMap<>();
	private final Map<PlacementKey, TileObject> scenePlacements = new HashMap<>();
	private final Map<PlacementKey, Integer> recentDespawnedStates = new HashMap<>();
	private final Set<WorldView> worldViews = identitySet();
	private final Set<ZoneKey> pendingZoneInvalidations = new HashSet<>();
	private final Map<Integer, Integer> visiblePlanes = new HashMap<>();
	private final Set<String> playedSpawnAnimations = new HashSet<>();
	private volatile Set<TileObject> suppressedSnapshot = Collections.emptySet();
	private volatile Set<TileObject> activeSnapshot = Collections.emptySet();
	private volatile boolean running;
	private volatile boolean hidden;
	private final Set<TileObject> pendingModels = identitySet();
	private Catalogue catalogue = Catalogue.current;
	private int zoneInvalidationBatchDepth;
	private boolean snapshotsDirty;

	@Inject
	PohCosmeticTransmogsManager(Client client, PohCosmeticTransmogsConfig config)
	{
		this.client = client;
		modelFactory = new Catalogue.ModelFactory(client, config);
	}

	void start(Map<String, String> initialSelections, boolean hidden)
	{
		DrawCallbacks callbacks = client.getDrawCallbacks();
		log.debug("Starting PoH furniture transmogs with renderer {}",
			callbacks == null ? "software" : callbacks.getClass().getName());
		this.hidden = hidden;
		running = true;
		catalogue = Catalogue.current;
		rebuildTargets();
		setSelections(initialSelections);
		rescanLoadedWorldViews();
		log.debug("PoH furniture scan found {} targets and activated {} replacements",
			sceneObjects.size(), activeReplacements.size());
	}

	void stop()
	{
		running = false;
		deactivateAll();
		// Rebuild cached scenery after removing replacements and ending suppression.
		invalidateAllKnownZones();
		sceneObjects.clear();
		scenePlacements.clear();
		recentDespawnedStates.clear();
		worldViews.clear();
		retiredObjects.clear();
		modelCache.clear();
		targetsById.clear();
		reportedModelFailures.clear();
		visiblePlanes.clear();
		playedSpawnAnimations.clear();
		selections.clear();
		pendingZoneInvalidations.clear();
		zoneInvalidationBatchDepth = 0;
		snapshotsDirty = false;
		pendingModels.clear();
	}

	void setSelections(Map<String, String> updated)
	{
		if (!running || selections.equals(updated))
		{
			return;
		}
		Set<String> changed = new HashSet<>(selections.keySet());
		changed.addAll(updated.keySet());
		changed.removeIf(key -> java.util.Objects.equals(selections.get(key), updated.get(key)));
		selections.clear();
		selections.putAll(updated);
		reportedModelFailures.clear();
		rebuildTargets();
		refreshObjects(changed);
		rescanLoadedWorldViews();
	}

	void setCatalogue(Catalogue catalogue)
	{
		this.catalogue = catalogue;
		if (!running)
		{
			return;
		}
		deactivateAll();
		invalidateAllKnownZones();
		clearSceneState();
		modelCache.clear();
		reportedModelFailures.clear();
		pendingModels.clear();
		rebuildTargets();
		rescanLoadedWorldViews();
	}

	void setHidden(boolean hidden)
	{
		if (!running)
		{
			return;
		}
		this.hidden = hidden;
		if (hidden)
		{
			deactivateAll();
			invalidateAllKnownZones();
		}
		else
		{
			refreshAllObjects();
		}
	}

	void refreshColours()
	{
		if (!running)
		{
			return;
		}
		beginZoneInvalidationBatch();
		try
		{
			modelCache.clear();
			refreshAllObjects();
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	void loadMissingModels()
	{
		if (running && !hidden)
		{
			for (TileObject object : new ArrayList<>(pendingModels))
			{
				refreshObject(object);
			}
		}
	}

	void addObject(@Nullable TileObject object)
	{
		if (!running || !(object instanceof GameObject))
		{
			return;
		}
		GameObject gameObject = (GameObject) object;
		TargetBinding target = targetsById.get(object.getId());
		if (target == null)
		{
			return;
		}
		if (sceneObjects.contains(object))
		{
			return;
		}

		// Construction state changes may spawn the new GameObject before the old
		// one despawns. Retire the indexed prior state for this exact placement.
		PlacementKey placement = new PlacementKey(gameObject, target);
		TileObject candidate = scenePlacements.get(placement);
		Integer recentState = recentDespawnedStates.remove(placement);
		int previousId = candidate != null && candidate != object
			? candidate.getId() : recentState == null ? -1 : recentState;
		boolean stateTransition = previousId >= 0
			&& target == targetsById.get(previousId)
			&& target.target.isOpen(previousId) != target.target.isOpen(object.getId());
		boolean opening = target.target.isOpen(object.getId());
		if (candidate != null && candidate != object)
		{
			// Suppress the retired state until its despawn event so it cannot flash.
			retiredObjects.add(candidate);
			suppressedObjects.add(candidate);
			deactivate(candidate);
			sceneObjects.remove(candidate);
			publishSnapshots();
		}
		if (sceneObjects.add(object))
		{
			scenePlacements.put(placement, object);
			worldViews.add(object.getWorldView());
			log.debug("Matched target object {} in world view {}",
				object.getId(), object.getWorldView());
			refreshObject(object);
			if (stateTransition)
			{
				transition(object, target, opening);
			}
		}
	}

	void removeObject(@Nullable TileObject object)
	{
		if (object != null)
		{
			deactivate(object);
			pendingModels.remove(object);
			boolean tracked = sceneObjects.remove(object);
			if (object instanceof GameObject)
			{
				TargetBinding target = targetsById.get(object.getId());
				if (target != null)
				{
					PlacementKey placement = new PlacementKey((GameObject) object, target);
					// Late despawns from a retired state must not replace the current state.
					if (tracked && target.target.isStateful())
					{
						recentDespawnedStates.put(placement, object.getId());
					}
					scenePlacements.remove(placement, object);
				}
				else
				{
					scenePlacements.values().removeIf(candidate -> candidate == object);
				}
			}
			retiredObjects.remove(object);
			suppressedObjects.remove(object);
			publishSnapshots();
		}
	}

	void removeWorldView(WorldView worldView)
	{
		visiblePlanes.remove(worldView.getId());
		worldViews.remove(worldView);
		beginZoneInvalidationBatch();
		try
		{
			for (TileObject object : new ArrayList<>(sceneObjects))
			{
				if (object.getWorldView() == worldView)
				{
					removeObject(object);
				}
			}
			recentDespawnedStates.keySet().removeIf(key -> key.worldView == worldView);
			retiredObjects.removeIf(object -> object.getWorldView() == worldView);
			suppressedObjects.removeIf(object -> object.getWorldView() == worldView);
			publishSnapshots();
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	void clearSceneState()
	{
		pendingModels.clear();
		deactivateAll();
		sceneObjects.clear();
		scenePlacements.clear();
		recentDespawnedStates.clear();
		worldViews.clear();
		retiredObjects.clear();
		playedSpawnAnimations.clear();
		visiblePlanes.clear();
	}

	void reconcileLoadedWorldViews()
	{
		beginZoneInvalidationBatch();
		try
		{
			rescanLoadedWorldViews();
			for (TileObject object : sceneObjects)
			{
				if (!activeReplacements.containsKey(object))
				{
					refreshObject(object);
				}
			}
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	void scanWorldView(@Nullable WorldView worldView)
	{
		if (worldView == null || worldView.getScene() == null)
		{
			return;
		}
		worldViews.add(worldView);
		Tile[][][] tiles = worldView.getScene().getTiles();
		if (tiles == null)
		{
			return;
		}
		beginZoneInvalidationBatch();
		try
		{
			for (Tile[][] plane : tiles)
			{
				if (plane == null)
				{
					continue;
				}
				for (Tile[] column : plane)
				{
					if (column == null)
					{
						continue;
					}
					for (Tile tile : column)
					{
						if (tile != null)
						{
							GameObject[] objects = tile.getGameObjects();
							if (objects != null)
							{
								for (GameObject object : objects)
								{
									addObject(object);
								}
							}
						}
					}
				}
			}
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	void syncVisibleLevels()
	{
		boolean changed = false;
		for (WorldView worldView : worldViews)
		{
			Integer previous = visiblePlanes.put(worldView.getId(), worldView.getPlane());
			changed |= previous == null || previous != worldView.getPlane();
		}
		if (changed)
		{
			refreshAllObjects();
		}
	}

	boolean shouldDrawObject(TileObject object)
	{
		// Suppress drawing, not scene membership: the original supplies menu actions and picking.
		Set<TileObject> snapshot = suppressedSnapshot;
		return !running || hidden || snapshot.isEmpty() || !snapshot.contains(object);
	}

	Set<TileObject> getActiveObjects()
	{
		return activeSnapshot;
	}

	boolean isSupportedRenderer()
	{
		return isSupportedRenderer(client.getDrawCallbacks());
	}

	private boolean isSupportedRenderer(@Nullable DrawCallbacks callbacks)
	{
		// GPU Legacy does not consult the object-suppression render callback.
		return client.isGpu() && callbacks != null
			&& !callbacks.getClass().getName().equals("info.sigterm.plugins.gpulegacy.GpuPlugin");
	}

	private void rebuildTargets()
	{
		targetsById.clear();
		targetsById.putAll(catalogue.bind(selections));
	}

	@Nullable
	private Model loadState(TargetBinding binding, GameObject object, boolean open)
	{
		Catalogue.Definition state = binding.appearance.state(open);
		return loadModel(binding, state, binding.appearance.stateKey(state),
			binding.calibration(object.sizeX(), object.sizeY()));
	}

	@Nullable
	private Model loadModel(TargetBinding binding, Catalogue.Definition definition, String stateKey,
		Catalogue.Calibration calibration)
	{
		ModelCacheKey key = new ModelCacheKey(binding.appearance.key, stateKey, definition.getModelIds(),
			modelFactory.recoloursPortal(binding.target, definition), calibration);
		Model model = modelCache.get(key);
		if (model == null)
		{
			model = modelFactory.load(binding.target, definition, calibration);
			if (model != null)
			{
				modelCache.put(key, model);
			}
		}
		return model;
	}

	private void refreshAllObjects()
	{
		refreshObjects(null);
	}

	private void refreshObjects(@Nullable Set<String> targetKeys)
	{
		beginZoneInvalidationBatch();
		try
		{
			for (TileObject object : sceneObjects)
			{
				if (targetKeys == null || changedTarget(object.getId(), targetKeys))
				{
					refreshObject(object);
				}
			}
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	private boolean changedTarget(int objectId, Set<String> keys)
	{
		for (String key : keys)
		{
			TargetSpec target = catalogue.targets.get(key);
			if (target != null)
			{
				for (int id : target.objectIds)
				{
					if (id == objectId)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private void refreshObject(TileObject object)
	{
		if (!(object instanceof GameObject))
		{
			deactivate(object);
			return;
		}
		GameObject gameObject = (GameObject) object;
		ResolvedReplacement resolved = resolve(gameObject);
		if (hidden || resolved == null)
		{
			deactivate(object);
			if (!retiredObjects.contains(object))
			{
				suppressedObjects.remove(object);
				publishSnapshots();
			}
			invalidateZone(object);
			return;
		}
		Catalogue.Definition definition = resolved.definition;
		Catalogue.Calibration calibration = resolved.calibration;
		Model model = resolved.model;
		WorldView worldView = object.getWorldView();
		if (worldView == null || !isVisibleLevel(object.getPlane(), worldView.getPlane()))
		{
			deactivate(object);
			suppressedObjects.add(object);
			publishSnapshots();
			invalidateZone(object);
			return;
		}

		String appearanceKey = resolved.appearance.key;
		RuneLiteObject replacement = resolved.appearance.bobbing
			? new BobbingRuneLiteObject(client) : client.createRuneLiteObject();
		replacement.setModel(model);
		int baseOrientation = (gameObject.getOrientation()
			+ targetsById.get(gameObject.getId()).target.orientationOffset) & 2047;
		int correction = calibration.getRotation();
		int defaultOrientation = (baseOrientation + correction) & 2047;
		LocalPoint anchor = occupiedTileCentre(gameObject);
		Catalogue.Alignment alignment = resolved.appearance.alignment;
		if (alignment != null && alignment != Catalogue.Alignment.NONE)
		{
			int width = resolved.appearance.getSizeX();
			int depth = resolved.appearance.getSizeY();
			if (defaultOrientation == 512 || defaultOrientation == 1536)
			{
				int swap = width;
				width = depth;
				depth = swap;
			}
			// Alignment is world-relative; manual offsets retain the target's orientation.
			int x = (gameObject.getSceneMaxLocation().getX() - gameObject.getSceneMinLocation().getX() + 1 - width) & 1;
			int y = (gameObject.getSceneMaxLocation().getY() - gameObject.getSceneMinLocation().getY() + 1 - depth) & 1;
			anchor = new LocalPoint(anchor.getX() + x * alignment.x * 64,
				anchor.getY() + y * alignment.y * 64, anchor.getWorldView());
		}
		if (calibration.getOffsetX() != 0 || calibration.getOffsetY() != 0)
		{
			anchor = offsetAnchor(anchor, baseOrientation,
				calibration.getOffsetX(), calibration.getOffsetY());
		}
		replacement.setLocation(anchor, object.getPlane());
		replacement.setZ(object.getZ());
		if (replacement instanceof BobbingRuneLiteObject)
		{
			((BobbingRuneLiteObject) replacement).setBaseZ(object.getZ());
		}
		replacement.setOrientation(defaultOrientation);
		int occupiedSpan = Math.max(definition.getSizeX(), definition.getSizeY());
		replacement.setRadius(Math.max(60, 64 * occupiedSpan - 4));

		if (definition.getAnimationId() >= 0)
		{
			Animation animation = client.loadAnimation(definition.getAnimationId());
			if (animation != null)
			{
				PostTransformAnimationController controller = new PostTransformAnimationController(
					client, animation, calibration);
				replacement.setAnimationController(controller);
				Animation spawn = definition.getSpawnAnimationId() < 0 ? null
					: client.loadAnimation(definition.getSpawnAnimationId());
				String spawnKey = spawnAnimationKey(gameObject);
				if (spawn != null && (!definition.isSpawnOnce()
					|| !playedSpawnAnimations.contains(spawnKey)))
				{
					controller.setAnimation(spawn);
					if (definition.isSpawnOnce())
					{
						controller.waitUntil = () -> spawnVisible(gameObject);
					}
					controller.setOnFinished(c ->
					{
						if (definition.isSpawnOnce())
						{
							playedSpawnAnimations.add(spawnKey);
						}
						c.setAnimation(animation);
						c.setOnFinished(AnimationController::loop);
					});
				}
				else
				{
					controller.setOnFinished(AnimationController::loop);
				}
			}
		}

		// Activate first, then atomically make this the replacement used to suppress
		// the original. This avoids a frame where the original reappears between two
		// replacement models during state, config, and renderer changes.
		replacement.setActive(true);
		boolean newlySuppressed = suppressedObjects.add(object);
		RuneLiteObject previous = activeReplacements.put(object, replacement);
		deactivateReplacement(previous);
		if (previous == null || newlySuppressed)
		{
			publishSnapshots();
		}
		log.debug("Activated appearance {} for target object {}",
			appearanceKey, object.getId());
		invalidateZone(object);
	}

	@Nullable
	private ResolvedReplacement resolve(GameObject object)
	{
		TargetBinding target = targetsById.get(object.getId());
		pendingModels.remove(object);
		if (target == null)
		{
			return null;
		}
		Catalogue.Definition definition = target.state(object.getId());
		Catalogue.Calibration calibration = target.calibration(object.sizeX(), object.sizeY());
		Model model = loadModel(target, definition, target.appearance.stateKey(definition), calibration);
		if (model == null)
		{
			pendingModels.add(object);
			if (reportedModelFailures.add(target.appearance.key))
			{
				log.warn("Unable to load appearance {}", target.appearance.key);
			}
			return null;
		}
		return new ResolvedReplacement(definition, model, target.appearance, calibration);
	}

	private void rescanLoadedWorldViews()
	{
		WorldView top = client.getTopLevelWorldView();
		if (top == null)
		{
			return;
		}
		beginZoneInvalidationBatch();
		try
		{
			scanWorldView(top);
			for (WorldView worldView : top.worldViews())
			{
				scanWorldView(worldView);
			}
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	private void startModelTransition(
		TileObject object, TargetBinding binding, boolean opening)
	{
		Catalogue.Recipe appearance = binding.appearance;
		Catalogue.Definition source = appearance;
		Animation animation = client.loadAnimation(appearance.transitionAnimationId);
		RuneLiteObject replacement = activeReplacements.get(object);
		if (animation == null || replacement == null)
		{
			return;
		}
		Model open = loadState(binding, (GameObject) object, true);
		Model closed = loadState(binding, (GameObject) object, false);
		Catalogue.Calibration calibration =
			binding.calibration(((GameObject) object).sizeX(), ((GameObject) object).sizeY());
		Model transition = loadTransitionModel(
			binding, source, appearance.transitionModelId, appearance.transitionAnimationId, calibration);
		if (open == null || closed == null || transition == null)
		{
			return;
		}

		// Hand the chest over before the animated model removes its copy. Closing
		// swaps the stable open chest directly to the closed model at the same point.
		replacement.setModel(open);
		replacement.setAnimationController(null);
		replacement.setActive(!opening);
		RuneLiteObject effect = client.createRuneLiteObject();
		effect.setModel(transition);
		effect.setLocation(replacement.getLocation(), replacement.getLevel());
		effect.setZ(replacement.getZ());
		effect.setOrientation(replacement.getOrientation());
		effect.setRadius(replacement.getRadius());
		PostTransformAnimationController controller =
			new PostTransformAnimationController(client, animation, calibration, !opening);
		controller.setTransitionPoint(appearance.transitionHandoff, () ->
		{
			replacement.setModel(opening ? open : closed);
			replacement.setActive(true);
		});
		Runnable finished = () ->
		{
			effect.setActive(false);
			transitionEffects.remove(replacement);
			replacement.setModel(opening ? open : closed);
			replacement.setActive(true);
		};
		if (opening)
		{
			controller.setOnFinished(ignored -> finished.run());
		}
		else
		{
			controller.setReverseFinished(finished);
		}
		effect.setAnimationController(controller);
		effect.setActive(true);
		transitionEffects.put(replacement, effect);
	}

	private void reverseOpenTransition(TileObject object, TargetBinding binding)
	{
		RuneLiteObject replacement = activeReplacements.get(object);
		Animation transition = client.loadAnimation(binding.appearance.open.getSpawnAnimationId());
		if (replacement == null || transition == null)
		{
			return;
		}
		Catalogue.Calibration calibration =
			binding.calibration(((GameObject) object).sizeX(), ((GameObject) object).sizeY());
		PostTransformAnimationController controller =
			new PostTransformAnimationController(client, transition, calibration, true);
		controller.setReverseFinished(() ->
		{
			if (activeReplacements.get(object) != replacement)
			{
				return;
			}
			Animation idle = client.loadAnimation(binding.appearance.closed.getAnimationId());
			replacement.setAnimationController(idle == null ? null
				: new PostTransformAnimationController(client, idle, calibration));
		});
		replacement.setAnimationController(controller);
	}

	private void startScaleTransition(TileObject object, TargetBinding binding, boolean opening)
	{
		Catalogue.Definition source = binding.appearance;
		RuneLiteObject replacement = activeReplacements.get(object);
		if (replacement == null)
		{
			return;
		}
		Animation idle = source.getAnimationId() < 0
			? null : client.loadAnimation(source.getAnimationId());
		Catalogue.Calibration calibration =
			binding.calibration(((GameObject) object).sizeX(), ((GameObject) object).sizeY());
		replacement.setAnimationController(new ScaleTransitionController(
			client, idle, calibration, opening, SCALE_TRANSITION_DURATION));
	}

	@Nullable
	private Model loadTransitionModel(TargetBinding binding,
		Catalogue.Definition source, int modelId, int animationId,
		Catalogue.Calibration calibration)
	{
		Catalogue.Definition transition = new Catalogue.Definition(
			source.getSizeX(), source.getSizeY(),
			new int[] {modelId}, animationId);
		transition.recolours = source.recolours;
		transition.colours.put(Catalogue.ColourChannel.CRYSTALS, source.colours(Catalogue.ColourChannel.CRYSTALS));
		return loadModel(binding, transition, "transition", calibration);
	}

	private boolean spawnVisible(GameObject object)
	{
		Widget loading = client.getWidget(InterfaceID.PohLoading.UNIVERSE);
		WorldView world = object.getWorldView();
		if (client.getGameState() != GameState.LOGGED_IN
			|| loading != null && !loading.isHidden()
			|| world == null || !isVisibleLevel(object.getPlane(), world.getPlane()))
		{
			return false;
		}
		Point point = Perspective.localToCanvas(client, occupiedTileCentre(object), object.getPlane());
		return point != null && point.getX() >= client.getViewportXOffset()
			&& point.getX() < client.getViewportXOffset() + client.getViewportWidth()
			&& point.getY() >= client.getViewportYOffset()
			&& point.getY() < client.getViewportYOffset() + client.getViewportHeight();
	}

	private static void applyCalibration(Model model,
		Catalogue.Calibration calibration)
	{
		int scaleX = calibration.signedScaleX();
		if (scaleX != 128 || calibration.getScaleHeight() != 128 || calibration.getScaleY() != 128)
		{
			model.scale(scaleX, calibration.getScaleHeight(), calibration.getScaleY());
		}
		if (calibration.getOffsetHeight() != 0)
		{
			model.translate(0, calibration.getOffsetHeight(), 0);
		}
	}

	private static LocalPoint occupiedTileCentre(GameObject object)
	{
		int x = (object.getSceneMinLocation().getX() + object.getSceneMaxLocation().getX() + 1) * 64;
		int y = (object.getSceneMinLocation().getY() + object.getSceneMaxLocation().getY() + 1) * 64;
		return new LocalPoint(x, y, object.getWorldView().getId());
	}

	private static LocalPoint offsetAnchor(LocalPoint point, int orientation, int offsetX, int offsetY)
	{
		double radians = orientation * Math.PI / 1024.0;
		double sin = Math.sin(radians);
		double cos = Math.cos(radians);
		int x = point.getX() + (int) Math.round(cos * offsetX + sin * offsetY);
		int y = point.getY() + (int) Math.round(cos * offsetY - sin * offsetX);
		return new LocalPoint(x, y, point.getWorldView());
	}

	private String spawnAnimationKey(GameObject object)
	{
		TargetBinding target = targetsById.get(object.getId());
		return object.getWorldView().getId() + ":" + object.getPlane() + ":"
			+ object.getSceneMinLocation().getX() + ":"
			+ object.getSceneMinLocation().getY() + ":"
			+ target.target.key;
	}

	static boolean isVisibleLevel(int objectPlane, int activePlane)
	{
		return objectPlane == activePlane || activePlane == 2 && objectPlane == 1;
	}

	private void deactivate(TileObject object)
	{
		RuneLiteObject replacement = activeReplacements.remove(object);
		deactivateReplacement(replacement);
		if (replacement != null)
		{
			publishSnapshots();
		}
	}

	private void deactivateReplacement(@Nullable RuneLiteObject replacement)
	{
		if (replacement != null)
		{
			replacement.setActive(false);
			RuneLiteObject effect = transitionEffects.remove(replacement);
			if (effect != null)
			{
				effect.setActive(false);
			}
		}
	}

	private void deactivateAll()
	{
		for (RuneLiteObject replacement : activeReplacements.values())
		{
			deactivateReplacement(replacement);
		}
		activeReplacements.clear();
		suppressedObjects.clear();
		publishSnapshots();
	}

	private void publishSnapshots()
	{
		if (zoneInvalidationBatchDepth > 0)
		{
			snapshotsDirty = true;
			return;
		}
		suppressedSnapshot = immutableIdentitySnapshot(suppressedObjects);
		activeSnapshot = immutableIdentitySnapshot(activeReplacements.keySet());
		snapshotsDirty = false;
	}

	private static <T> Set<T> identitySet()
	{
		return Collections.newSetFromMap(new IdentityHashMap<>());
	}

	private static <T> Set<T> immutableIdentitySnapshot(Collection<T> values)
	{
		if (values.isEmpty())
		{
			return Collections.emptySet();
		}
		Set<T> snapshot = identitySet();
		snapshot.addAll(values);
		return Collections.unmodifiableSet(snapshot);
	}

	private void invalidateAllKnownZones()
	{
		beginZoneInvalidationBatch();
		try
		{
			for (TileObject object : sceneObjects)
			{
				invalidateZone(object);
			}
		}
		finally
		{
			endZoneInvalidationBatch();
		}
	}

	private void invalidateZone(TileObject object)
	{
		DrawCallbacks callbacks = client.getDrawCallbacks();
		WorldView worldView = object.getWorldView();
		if (!isSupportedRenderer(callbacks) || worldView == null || worldView.getScene() == null)
		{
			return;
		}

		GameObject gameObject = (GameObject) object;
		int zoneX = gameObject.getSceneMinLocation().getX() >> 3;
		int zoneY = gameObject.getSceneMinLocation().getY() >> 3;
		if (worldView.getId() == WorldView.TOPLEVEL)
		{
			int extendedOffset = (Constants.EXTENDED_SCENE_SIZE - Constants.SCENE_SIZE) / 2;
			zoneX += extendedOffset >> 3;
			zoneY += extendedOffset >> 3;
		}
		int size = worldView.getId() == WorldView.TOPLEVEL
			? Constants.EXTENDED_SCENE_SIZE : Math.max(worldView.getSizeX(), worldView.getSizeY());
		int zoneCount = (size + 7) >> 3;
		if (zoneX >= 0 && zoneY >= 0 && zoneX < zoneCount && zoneY < zoneCount)
		{
			ZoneKey zone = new ZoneKey(worldView.getScene(), zoneX, zoneY);
			if (zoneInvalidationBatchDepth > 0)
			{
				pendingZoneInvalidations.add(zone);
			}
			else
			{
				callbacks.invalidateZone(zone.scene, zone.x, zone.y);
			}
		}
	}

	private void beginZoneInvalidationBatch()
	{
		zoneInvalidationBatchDepth++;
	}

	private void endZoneInvalidationBatch()
	{
		if (--zoneInvalidationBatchDepth != 0)
		{
			return;
		}
		if (snapshotsDirty)
		{
			publishSnapshots();
		}
		DrawCallbacks callbacks = client.getDrawCallbacks();
		try
		{
			if (isSupportedRenderer(callbacks))
			{
				for (ZoneKey zone : pendingZoneInvalidations)
				{
					callbacks.invalidateZone(zone.scene, zone.x, zone.y);
				}
			}
		}
		finally
		{
			pendingZoneInvalidations.clear();
		}
	}

	private void transition(TileObject object, TargetBinding binding, boolean opening)
	{
		Catalogue.Recipe appearance = binding.appearance;
		if (!binding.target.isStateful())
		{
			return;
		}
		if (appearance.transitionModelId >= 0)
		{
			startModelTransition(object, binding, opening);
		}
		else if (!opening && appearance.open.getSpawnAnimationId() >= 0)
		{
			reverseOpenTransition(object, binding);
		}
		else if (binding.target.scaleTransition && appearance.closed == appearance.open)
		{
			startScaleTransition(object, binding, opening);
		}
	}
	@Value
	private static class ResolvedReplacement
	{
		Catalogue.Definition definition;
		Model model;
		Catalogue.Recipe appearance;
		Catalogue.Calibration calibration;
	}

	@Value
	private static class ModelCacheKey
	{
		String appearanceKey;
		String stateKey;
		int[] modelIds;
		boolean portalRecolour;
		int scaleX;
		int scaleHeight;
		int scaleY;
		int offsetHeight;
		boolean flipX;
		@EqualsAndHashCode.Exclude
		Catalogue.Calibration calibration;

		private ModelCacheKey(String appearanceKey, String stateKey, int[] modelIds, boolean portalRecolour,
			Catalogue.Calibration calibration)
		{
			this.appearanceKey = appearanceKey;
			this.stateKey = stateKey;
			this.modelIds = modelIds;
			this.portalRecolour = portalRecolour;
			scaleX = calibration.getScaleX();
			scaleHeight = calibration.getScaleHeight();
			scaleY = calibration.getScaleY();
			offsetHeight = calibration.getOffsetHeight();
			flipX = calibration.isFlipX();
			this.calibration = calibration;
		}
	}

	private static final class PlacementKey
	{
		private final WorldView worldView;
		private final int plane;
		private final int x;
		private final int y;
		private final String target;

		private PlacementKey(GameObject object, TargetBinding target)
		{
			worldView = object.getWorldView();
			plane = object.getPlane();
			x = object.getSceneMinLocation().getX();
			y = object.getSceneMinLocation().getY();
			this.target = target.target.key;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof PlacementKey))
			{
				return false;
			}
			PlacementKey key = (PlacementKey) other;
			return worldView == key.worldView && plane == key.plane
				&& x == key.x && y == key.y && target.equals(key.target);
		}

		@Override
		public int hashCode()
		{
			int hash = System.identityHashCode(worldView);
			hash = 31 * hash + plane;
			hash = 31 * hash + x;
			hash = 31 * hash + y;
			return 31 * hash + target.hashCode();
		}
	}

	private static final class ZoneKey
	{
		private final Scene scene;
		private final int x;
		private final int y;

		private ZoneKey(Scene scene, int x, int y)
		{
			this.scene = scene;
			this.x = x;
			this.y = y;
		}

		@Override
		public boolean equals(Object other)
		{
			if (this == other)
			{
				return true;
			}
			if (!(other instanceof ZoneKey))
			{
				return false;
			}
			ZoneKey zone = (ZoneKey) other;
			return scene == zone.scene && x == zone.x && y == zone.y;
		}

		@Override
		public int hashCode()
		{
			int hash = 31 * System.identityHashCode(scene) + x;
			return 31 * hash + y;
		}
	}

	/** Applies visual fitting to the completed pose, including its animated translations. */
	private static final class PostTransformAnimationController extends AnimationController
	{
		private final Catalogue.Calibration calibration;
		private final boolean reverse;
		private int reverseElapsedTicks;
		private Runnable reverseFinished = () -> { };
		private Runnable transitionPoint;
		private int transitionPercent = 50;
		private boolean reverseFinishedRun;
		private BooleanSupplier waitUntil;

		private PostTransformAnimationController(Client client, Animation animation,
			Catalogue.Calibration calibration)
		{
			this(client, animation, calibration, false);
		}

		private PostTransformAnimationController(Client client, Animation animation,
			Catalogue.Calibration calibration, boolean reverse)
		{
			super(client, animation);
			this.calibration = calibration;
			this.reverse = reverse;
			if (reverse)
			{
				setFrame(Math.max(0, animation.getDuration() - 1));
			}
		}

		@Override
		public void tick(int ticks)
		{
			if (waitUntil != null)
			{
				if (!waitUntil.getAsBoolean())
				{
					return;
				}
				waitUntil = null;
				// Do not consume time accumulated while the scene was hidden.
				return;
			}
			Animation animation = getAnimation();
			if (animation == null)
			{
				return;
			}
			if (!reverse)
			{
				super.tick(ticks);
				runTransitionPoint(animation);
				return;
			}
			if (animation.isMayaAnim())
			{
				setFrame(Math.max(0, getFrame() - ticks));
				runTransitionPoint(animation);
				finishReverseAtFirstFrame();
				return;
			}
			reverseElapsedTicks += ticks;
			int[] frameLengths = animation.getFrameLengths();
			while (getFrame() > 0 && reverseElapsedTicks > frameLengths[getFrame()])
			{
				reverseElapsedTicks -= frameLengths[getFrame()];
				setFrame(getFrame() - 1);
			}
			runTransitionPoint(animation);
			finishReverseAtFirstFrame();
		}

		private void setTransitionPoint(int percent, Runnable action)
		{
			transitionPercent = percent;
			transitionPoint = action;
		}

		private void runTransitionPoint(Animation animation)
		{
			if (transitionPoint == null)
			{
				return;
			}
			int duration = animation.getDuration();
			int frame = duration * (reverse ? 100 - transitionPercent : transitionPercent) / 100;
			if (reverse ? getFrame() <= frame : getFrame() >= frame)
			{
				Runnable action = transitionPoint;
				transitionPoint = null;
				action.run();
			}
		}

		private void setReverseFinished(Runnable reverseFinished)
		{
			this.reverseFinished = reverseFinished;
		}

		private void finishReverseAtFirstFrame()
		{
			if (getFrame() == 0 && !reverseFinishedRun)
			{
				reverseFinishedRun = true;
				reverseFinished.run();
			}
		}

		@Override
		public Model animate(Model model, @Nullable AnimationController other)
		{
			Model posed = super.animate(model, other);
			applyCalibration(posed, calibration);
			return posed;
		}
	}

	private static final class ScaleTransitionController extends AnimationController
	{
		private final Client client;
		private static final int OPEN_SCALE = 160;
		private final Catalogue.Calibration calibration;
		private final boolean opening;
		private final int duration;
		private int elapsed;
		private Model finalPose;

		private ScaleTransitionController(Client client, @Nullable Animation animation,
			Catalogue.Calibration calibration, boolean opening, int duration)
		{
			super(client, animation);
			this.client = client;
			this.calibration = calibration;
			this.opening = opening;
			this.duration = duration;
		}

		@Override
		public void tick(int ticks)
		{
			if (getAnimation() != null)
			{
				super.tick(ticks);
			}
			elapsed = Math.min(duration, elapsed + ticks);
		}

		@Override
		public Model animate(Model model, @Nullable AnimationController other)
		{
			if (finalPose != null)
			{
				return finalPose;
			}
			Model posed = super.animate(model, other);
			if (getAnimation() != null)
			{
				applyCalibration(posed, calibration);
			}
			posed.calculateBoundsCylinder();
			int bottom = posed.getBottomY();
			int delta = (OPEN_SCALE - 128) * elapsed / duration;
			int scale = opening ? 128 + delta : OPEN_SCALE - delta;
			posed.scale(scale, scale, scale);
			posed.translate(0, bottom - bottom * scale / 128, 0);
			if (elapsed == duration && getAnimation() == null && other == null)
			{
				// Animation transforms use scratch models; retain an independent copy.
				finalPose = client.mergeModels(posed);
			}
			return posed;
		}
	}

	private static final class BobbingRuneLiteObject extends RuneLiteObject
	{
		private static final int BOB_CYCLE = 160;
		private static final int BOB_HEIGHT = 4;
		private int baseZ;
		private int phase;

		private BobbingRuneLiteObject(Client client)
		{
			super(client);
		}

		private void setBaseZ(int baseZ)
		{
			this.baseZ = baseZ;
		}

		@Override
		public void tick(int ticks)
		{
			super.tick(ticks);
			phase = (phase + ticks) % BOB_CYCLE;
			setZ(baseZ - Math.round(BOB_HEIGHT *
				(float) Math.sin(phase * Math.PI * 2 / BOB_CYCLE)));
		}
	}
}

package com.pohcosmetictransmogs;

import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.AppearanceOption;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.ArmourAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.ChestAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.EntranceAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.StorageAppearance;
import com.pohcosmetictransmogs.PohCosmeticTransmogsConfig.WardrobeAppearance;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** Configuration slots reference target keys; target mechanics belong to the catalogue. */
@Getter
@RequiredArgsConstructor
enum PohTargetSlot
{
	ENTRANCE_PORTAL("entrancePortal", "entrance_portal"),
	CAPE_RACK("capeRack", "cape_rack"),
	TREASURE_CHEST("treasureChest", "treasure_chest"),
	FANCY_DRESS_BOX("fancyDressBox", "fancy_dress_box"),
	ARMOUR_CASE("armourCase", "armour_case"),
	TOY_BOX("toyBox", "toy_box"),
	MAGIC_WARDROBE("magicWardrobe", "magic_wardrobe");

	private final String configKey;
	private final String targetKey;

	static boolean isConfigKey(String key)
	{
		for (PohTargetSlot slot : values())
		{
			if (slot.configKey.equals(key))
			{
				return true;
			}
		}
		return false;
	}
	Enum<?> option(String appearanceKey)
	{
		switch (this)
		{
			case ENTRANCE_PORTAL: return AppearanceOption.find(EntranceAppearance.values(), appearanceKey);
			case MAGIC_WARDROBE: return AppearanceOption.find(WardrobeAppearance.values(), appearanceKey);
			case TREASURE_CHEST:
			case TOY_BOX:
			case FANCY_DRESS_BOX: return AppearanceOption.find(ChestAppearance.values(), appearanceKey);
			case ARMOUR_CASE: return AppearanceOption.find(ArmourAppearance.values(), appearanceKey);
			default: return AppearanceOption.find(StorageAppearance.values(), appearanceKey);
		}
	}

}
